package cli

import (
	"context"
	"errors"
	"fmt"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/gitremote"
	"github.com/entireio/cli/internal/coreapi"
)

// entireAPIPlacement is a repo's entire-api routing coordinates, read from its
// mirror: the cell that hosts it (fills {cell} in ENTIRE_API_BASE_URL_TEMPLATE)
// and the jurisdiction that homes it (fills {jurisdiction} in the audience and
// token-minting-core templates). Both must be present for a repo to be routable
// to entire-api; older cores omit them.
type entireAPIPlacement struct {
	Cell         string
	Jurisdiction string
	ClusterHost  string
}

// errRepoNotRoutable means the repo has no mirror carrying both a cell and a
// jurisdiction, so the CLI can't address its entire-api. Callers fall back to
// the data API rather than treating this as fatal.
var errRepoNotRoutable = errors.New("repo has no entire-api-routable mirror (missing cell/jurisdiction)")

// forgeToMirrorProvider maps a gitremote forge identifier (e.g. "gh") to the
// upstream provider the control plane records mirrors under (e.g. "github").
// entire-api routing only supports GitHub mirrors today.
func forgeToMirrorProvider(forge string) (string, bool) {
	switch strings.ToLower(strings.TrimSpace(forge)) {
	case "gh", "github":
		return mirrorCloneProviderGitHub, true
	default:
		return "", false
	}
}

// selectRoutablePlacement picks the entire-api placement from a repo's mirrors.
// Only mirrors carrying both a cell and a jurisdiction are eligible. When the
// repo is mirrored on several clusters, preferredCluster wins if it matches;
// otherwise the first routable mirror is used. This mirrors entire.io/api's
// resolveCell (`preferred ?? matches[0]`), including its "filter to routable
// before selecting" ordering so a non-routable row first doesn't mask a
// routable sibling.
func selectRoutablePlacement(mirrors []coreapi.Mirror, preferredCluster string) (entireAPIPlacement, bool) {
	var first *entireAPIPlacement
	for i := range mirrors {
		cell := strings.TrimSpace(mirrors[i].Cell.Or(""))
		jur := strings.TrimSpace(mirrors[i].Jurisdiction.Or(""))
		if cell == "" || jur == "" {
			continue
		}
		p := entireAPIPlacement{Cell: cell, Jurisdiction: jur, ClusterHost: mirrors[i].ClusterHost}
		if preferredCluster != "" && strings.EqualFold(mirrors[i].ClusterHost, preferredCluster) {
			return p, true
		}
		if first == nil {
			routable := p
			first = &routable
		}
	}
	if first != nil {
		return *first, true
	}
	return entireAPIPlacement{}, false
}

// resolveCurrentRepoPlacement resolves the entire-api placement for the repo in
// the current working directory, via its "origin" remote. It lists the repo's
// mirrors through the control plane (c) and selects a routable one. It returns
// errRepoNotRoutable when the repo is unmirrored or its mirrors predate
// cell/jurisdiction metadata.
func resolveCurrentRepoPlacement(ctx context.Context, c *coreapi.Client) (entireAPIPlacement, error) {
	forge, owner, repo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
	if err != nil {
		return entireAPIPlacement{}, fmt.Errorf("resolve current repo: %w", err)
	}
	provider, ok := forgeToMirrorProvider(forge)
	if !ok {
		return entireAPIPlacement{}, fmt.Errorf("unsupported forge %q for entire-api routing", forge)
	}

	mirrors, err := listMirrorsForRepo(ctx, c, provider, strings.ToLower(owner), repo)
	if err != nil {
		return entireAPIPlacement{}, fmt.Errorf("list mirrors for %s/%s: %w", owner, repo, err)
	}

	placement, ok := selectRoutablePlacement(mirrors, "")
	if !ok {
		return entireAPIPlacement{}, fmt.Errorf("%s/%s: %w", owner, repo, errRepoNotRoutable)
	}
	return placement, nil
}

package cli

import (
	"testing"

	"github.com/entireio/cli/internal/coreapi"
