// errRepoNotRoutable means the repo has no mirror carrying both a cell and a
// jurisdiction, so the CLI can't address its entire-api. It is not fatal:
// callers fall back to the data API.
var errRepoNotRoutable = errors.New("repo has no entire-api-routable mirror (missing cell/jurisdiction)")

// resolveCurrentRepoPlacement resolves the entire-api placement for the repo in
// the current working directory, via its "origin" remote. It lists the repo's
// mirrors through the control plane (c) and selects a routable one, returning
// errRepoNotRoutable when the repo is unmirrored or its mirrors predate
// cell/jurisdiction metadata.
func resolveCurrentRepoPlacement(ctx context.Context, c *coreapi.Client) (entireAPIPlacement, error) {
	forge, owner, repo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
	if err != nil {
		return entireAPIPlacement{}, fmt.Errorf("resolve current repo: %w", err)
	}
	provider, ok := forgeToMirrorProvider(forge)
	if !ok {
		return entireAPIPlacement{}, fmt.Errorf("unsupported forge %q for entire-api routing", forge)
	}

	mirrors, err := listMirrorsForRepo(ctx, c, provider, strings.ToLower(owner), repo)
	if err != nil {
		return entireAPIPlacement{}, fmt.Errorf("list mirrors for %s/%s: %w", owner, repo, err)
	}

	placement, ok := selectRoutablePlacement(mirrors, "")
	if !ok {
		return entireAPIPlacement{}, fmt.Errorf("%s/%s: %w", owner, repo, errRepoNotRoutable)
	}
	return placement, nil
}

// newEntireAPIClientForCurrentRepo builds an api.Client pointed at the entire-api
// cell hosting the current repo, carrying a jurisdictional identity token.
//
// ok=false with a nil error means "entire-api not in play": either the operator
// hasn't set the ENTIRE_API_BASE_URL_TEMPLATE / ENTIRE_API_AUDIENCE_TEMPLATE
// pair, or the repo has no routable mirror — so the caller falls back to the
// data API. Genuine failures (control-plane unreachable, token exchange
// rejected, malformed template) return an error rather than silently masking a
// misconfigured opt-in.
func newEntireAPIClientForCurrentRepo(ctx context.Context, insecureHTTP bool) (*api.Client, bool, error) {
	baseTemplate := api.EntireAPIBaseURLTemplate()
	audTemplate := api.EntireAPIAudienceTemplate()
	if baseTemplate == "" || audTemplate == "" {
		return nil, false, nil
	}

	core, err := coreapi.New()
	if err != nil {
		return nil, false, fmt.Errorf("entire-api routing needs the control plane: %w", err)
	}
	placement, err := resolveCurrentRepoPlacement(ctx, core)
	if err != nil {
		if errors.Is(err, errRepoNotRoutable) {
			return nil, false, nil
		}
		return nil, false, err
	}

	baseURL, err := api.BuildEntireAPIBaseURL(baseTemplate, placement.Cell)
	if err != nil {
		return nil, false, err
	}
	audience, err := api.BuildEntireAPIAudience(audTemplate, placement.Jurisdiction)
	if err != nil {
		return nil, false, err
	}

	if insecureHTTP {
		auth.EnableInsecureHTTP()
	} else if err := api.RequireSecureURL(baseURL); err != nil {
		return nil, false, fmt.Errorf("entire-api base URL check: %w", err)
	}

	token, err := auth.ResolveEntireAPIToken(ctx, audience)
	if err != nil {
		return nil, false, err
	}
	return api.NewClientWithBaseURL(token, baseURL), true, nil
}

// runAuthenticatedActivityAPI runs fn with an authenticated client for the
// activity/recap surface: the entire-api cell for the current repo when it is
// configured and the repo is routable, otherwise the data API. Both serve the
// same /me/* paths, so fn is agnostic to which client it receives.
func runAuthenticatedActivityAPI(ctx context.Context, errW io.Writer, insecureHTTP bool, fn func(context.Context, *api.Client) error) error {
	client, ok, err := newEntireAPIClientForCurrentRepo(ctx, insecureHTTP)
	if err != nil {
		return renderDataAPIAuthError(errW, err)
	}
	if !ok {
		return runAuthenticatedDataAPI(ctx, errW, insecureHTTP, fn)
	}
	return fn(ctx, client)
}

