// ?repo= (its team/contributors scope): the current repo's ULID when routed to
// entire-api (which addresses repos by id), or its owner/repo slug on the data
// API (which addresses them by name). Empty when the current repo can't be
// determined — recap then shows the personal side only.
//
// It prefers the entire-api cell for the current repo. recap tolerates not
// being logged in (it renders and lets the server answer 401), so an
// ErrNotLoggedIn from the entire-api attempt falls through to the data API
// rather than erroring; every other failure surfaces.
func newRecapClient(ctx context.Context, insecureHTTP bool) (*api.Client, string, error) {
	ec, ok, err := newEntireAPIClientForCurrentRepo(ctx, insecureHTTP)
	switch {
	case err != nil && !errors.Is(err, auth.ErrNotLoggedIn):
		return nil, "", err
	case ok:
		return ec.client, ec.repoID, nil
	}

	if insecureHTTP {
		auth.EnableInsecureHTTP()
	}
	token, err := auth.ResolveDataAPIToken(ctx, api.BaseURL())
	if errors.Is(err, auth.ErrNotLoggedIn) {
		token = ""
		err = nil
	}
	if err != nil {
		return nil, "", err
	}
	if token != "" && !insecureHTTP {
		if err := api.RequireSecureURL(api.BaseURL()); err != nil {
			return nil, "", fmt.Errorf("base URL check: %w", err)
		}
	}
	return api.NewClient(token), currentRepoSlug(ctx), nil
}

